void Holder::run() const {
    std::optional<Flat> __slot_1;
    std::optional<Flat> __slot_2;
    std::optional<Flat> __slot_3;
    Flat* p;
    Flat* saved;
    for (int32_t i = 0; i < 2; ++i) {
        if ((i == 0)) {
            p = &*(__slot_1 = Flat(i));
        } else {
            p = &*(__slot_2 = Flat(::tpy::neg_check<int32_t>(i)));
        }
        saved = p;
    }
    p->n = ::tpy::add_check<int32_t>(p->n, 100);
    std::cout << "method" << " " << p->n << " " << saved->n << "\n";
    p = &*(__slot_3 = Flat(9));
    std::cout << "method" << " " << p->n << " " << saved->n << "\n";
}
